```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

int main() {
    // Define the word to search for
    std::string search_word = "example";

    // Open the input file
    std::ifstream input_file("input.txt");

    // Check if the file opened successfully
    if (!input_file.is_open()) {
        std::cerr << "Error opening input file.\n";
        return 1;
    }

    // Create a map to store the word counts
    std::unordered_map<std::string, int> word_counts;

    // Read the file line by line and update the word counts
    std::string line;
    while (std::getline(input_file, line)) {
        // Convert the line to lowercase to make case-insensitive search
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Split the line into words and update the word counts
        std::istringstream iss(line);
        std::string word;
        while (iss >> word) {
            if (word == search_word) {
                // Increment the count for the search word
                ++word_counts[search_word];
            }
        }
    }

